<?php require_once "../config/conexao.php"; $id=(int)($_GET["id"]??0); if($id<=0)die("OS inválida."); $conexao->begin_transaction(); try { if(!$conexao->query("DELETE FROM servico_has_os WHERE os_id_os=$id")) throw new Exception($conexao->error); if(!$conexao->query("DELETE FROM os_has_mecanico WHERE os_id_os=$id")) throw new Exception($conexao->error); if(!$conexao->query("DELETE FROM os WHERE id_os=$id")) throw new Exception($conexao->error); $conexao->commit(); header("Location: os.php"); exit(); } catch(Exception $e) { $conexao->rollback(); die("Erro ao excluir OS: ".$e->getMessage()); } ?>